                ["bt.ev.boss.self"] = new[] { "히히, 노래로 만들자!", "다음엔 나도 칠 거야!", "잔치다, {partner}! 미드 꺼내!" },
                ["bt.ev.weather.rain.react"] = new[] { "{who}, 비다! 히히, 머리 감자!", "비 온다, {who}! 개구리 나오겠다!" },
