                ["bt.item.open"] = new[] { "{item}! {dir}에 산더미야, 히히.", "{partner}, {dir} {item} 기억나? 내가 찾았잖아!", "{item|은} {dir}! 신들이 거기 쌓아 뒀어.", "{dir}에 {item|이} 반짝반짝했어!", "{partner}, {item} 보물 지도 그려 줄까? {dir}!", "{item|이} 필요해? {dir}에 달려가면 돼, 히히.", "{dir}의 {item}, 내가 몰래 점찍어 뒀지!", "{item|은} 내 거야! {dir}에 있는 건 전부!", "{partner}, {dir}에 {item|이} 잔뜩이야. 소풍 갈래?", "{item} 찾는 데는 내 코가 최고야, 히히.", "{dir}! {item}! 기억해, 기억해!", "{item|이} 날 부르는 소리가 {dir}에서 들려!", "{partner}, {item} 한 무더기 들고 오면 칭찬해 줄 거지?", "{dir}에 {item|이} 있는 거, 아무한테도 말하지 마! 히히.", "{item|은} {dir}에서 자라나 봐. 계속 있어!" },
                ["bt.item.reply"] = new[] { "히히, 다 가져오자!", "나도 알아! 내가 먼저 알았어.", "가자 가자!", "보물 지도 좋아! 나도 그릴래!", "히히, 소풍이다!", "내가 더 많이 들고 올 거야!", "비밀이야? 쉿, 히히.", "거기 가는 길에 버섯도 있었어!", "내 코도 좋아! 킁킁.", "칭찬해 줄게! 히히.", "나도 점찍어 뒀는데!", "다 들고 오면 춤춰야지!", "{item|은} 많을수록 좋아!", "히히, 오늘 밤 꿈에 나오겠다.", "좋아, 내일 아침 일찍 가자!" },
                ["bt.mead.open"] = new[] { "미드! 미드 마시고 싶어! 히히.", "{partner}, 몰래 한 병 마실까?", "오딘도 미드를 좋아해. 그러니까 우리도!", "히히, 미드 통에서 꿀 냄새가 솔솔!", "{partner}, 미드에 버섯 넣으면 어떻게 될까?", "벌한테 쏘여도 미드를 위해서라면 괜찮아!", "미드 마시면 노래가 저절로 나와! 히히.", "오딘이 시를 미드로 얻었대! 나도 시인이 될래!", "{partner}, 미드 많이 마시기 내기할래?", "미드 한 잔에 신들 이야기 하나!", "꿀벌들아, 더 일해라! 히히.", "미드 통을 배에 싣고 떠나자!", "히히, 어제 한 모금 몰래 마셨어.", "미드는 황금색이야. 해를 마시는 거지!", "잔 부딪치는 소리가 제일 좋아!" },
                ["bt.mead.reply"] = new[] { "히히, 두 잔!", "좋아! 신들을 위해 건배!", "벌써 목이 마르다!", "히히, 건배!", "나도 나도! 세 잔!", "좋아! 노래도 부르자!", "오딘을 위하여! 히히.", "한 잔 더! 아니, 두 잔!", "히히, 쉿, 비밀이야.", "미드 최고!", "벌써 기분이 좋아지는 것 같아!", "히히, 그럼 오늘은 축제다!", "내 잔이 제일 커!", "좋아! 근데 네가 따라!", "신들도 한 잔 줘야지!" },
                ["bt.night.open"] = new[] { "밤이다! 늑대들이 노래해, 히히.", "{partner}, 저 별 봐! 오딘의 눈이야!", "밤엔 유령이 나온대. 히히, 무섭지?", "{partner}, 별똥별이다! 소원 빌어!", "밤엔 불 옆이 제일 좋아. 히히, 발 따뜻해.", "달이 꼭 치즈 같아!", "{partner}, 무서운 얘기 해 줄까?", "부엉이가 날 부르는 것 같아!", "밤하늘에 배가 떠다니는 것 같아, 히히.", "{partner}, 오늘 밤엔 잠 안 잘 거야! ...아마도.", "별을 세다가 백까지 셌어! 그다음은 몰라, 히히.", "밤엔 그림자가 춤을 춰!", "{partner}, 숲에서 뭔가 반짝였어! 눈이야? 히히.", "밤바람이 간지러워!", "{partner}, 우리 몰래 밤 소풍 갈까? 히히." },
                ["bt.night.reply"] = new[] { "히히, 안 무서워!", "별 하나 따다 줄까?", "잠은 발할라에서 자면 돼!", "소원 빌었어! 비밀이야.", "무서운 얘기 좋아! ...조금만.", "치즈? 배고파졌잖아!", "부엉이한테 대답해 줘!", "나도 셀래! 하나, 둘...", "히히, 그림자 놀이 하자!", "반짝이는 거? 으, 반딧불이야. 아마도.", "나도 잠 안 잘 거야! ...하암.", "밤 소풍? 좋아! 몰래몰래!", "늑대 흉내 낼까? 아우우!", "히히, 이불 속이 제일 안전해.", "별이 날 보고 웃는 것 같아!" },
                ["bt.pit.open"] = new[] { "{dir} 구덩이! 거기 빠졌을 때 진짜 무서웠어, 히히.", "{partner}, {dir} 구덩이 조심해! 땅이 입을 벌리고 있어.", "{dir} 구덩이, 땅이 하품한 자리야!", "{partner}, 나 {dir} 구덩이에서 노래 불렀어. 아무도 안 왔어, 히히.", "{dir}엔 땅이 쑥 꺼져! 발밑 조심!", "{partner}, {dir} 구덩이 기억나? 나 거기서 별 봤어.", "구덩이에 빠지면 하늘이 동그래져, 히히.", "{dir} 구덩이엔 트롤이 숨어 있을지도 몰라!", "{partner}, {dir}에 갈 때 나 손 잡아 줘! 히히.", "{dir} 그 구덩이, 이름 지어 줬어. 꿀꺽이!", "땅이 날 삼키려고 했어! {dir}에서!", "{dir} 구덩이, 다음엔 뛰어넘을 거야!", "{partner}, {dir} 구덩이에 돌 던지면 메아리 들려, 히히.", "나 구덩이 탈출 대장이야! {dir}에서 배웠어.", "{dir}엔 가기 싫어... 꿀꺽이가 배고플걸." },
                ["bt.pit.reply"] = new[] { "히히, 나 거기서 춤췄잖아!", "그 구덩이, 로키가 판 게 분명해!", "꿀꺽이? 히히, 이름 좋다!", "손 잡아 줄게! 대신 너도 잡아 줘.", "나도 빠질 뻔했어!", "뛰어넘기? 나랑 시합하자!", "땅도 배고픈가 봐, 히히.", "메아리 놀이 하자!", "트롤? 으, 그럼 빨리 지나가자!", "다음엔 밧줄 들고 가자!", "히히, 탈출 대장 인정!", "거기 꽃 심어 둘까? 그럼 안 빠지지!", "구덩이 안에서 본 별, 예뻤어?", "나도 거기서 엉덩방아 찧었어!", "땅이 하품하면 우리도 하품하자, 하암!" },
                ["bt.sea.open"] = new[] { "배! 큰 배를 만들고 싶어. 용머리를 단 거!", "{partner}, 내가 배 만들면 같이 타자, 히히.", "바다는 신들의 길이야. 언젠가 건널 거야.", "바다 냄새! 짭짤해서 좋아!", "{partner}, 물고기들도 노래 부를까? 히히.", "파도가 나를 부르고 있어! 들려?", "배 만들 나무 봤어! 아주 곧은 거!", "바다뱀 등에 타 보고 싶어. 히히.", "{partner}, 돛에 용 그려 줄까?", "저 끝까지 노 저으면 세상 끝이 보일까?", "배는 살아 있어. 나무가 기억하거든.", "히히, 바다에 뛰어들면 시원하겠다!", "별을 따라가면 신들의 섬이 나올 거야!", "내 배는 바람보다 빠를 거야!", "{partner}, 바다 위에서 자 본 적 있어?" },
