                ["bt.skill.open"] = new[] { "내 {skill} {level}! 히히, 대단하지?", "{partner}, 나 {skill} {level|이야}! 네 {pskill|은} {plevel}이지? 히히.", "{skill} {level}! 신들도 놀라셨을걸.", "{skill|이} {level|이야}! 손이 막 저절로 움직여!", "{partner}, 내 {skill} 봤어? 번개처럼 빨라, 히히.", "{skill} {level}! 다음엔 두 배로 할 거야.", "내 {skill|은} 이제 {level|이야}! 박수!", "{partner}, 네 {pskill} {plevel}? 히히, 나도 곧 그만큼 해!", "{skill|이} 늘었어! {level}! 오늘 저녁은 내가 쏠게.", "{skill} {level}... 히히, 손가락이 근질근질해.", "{partner}, 나 {skill} 선생님 할래! 벌써 {level|이야}!", "{skill|이} {level|이라}니! 나 천재 아냐?", "{skill} {level}! 토르도 내 솜씨에 반했을걸.", "오늘 {skill} 하다가 콧노래가 나왔어! {level|이야}.", "{partner}, {skill} {level}! 축하 노래 불러 줘!" },
                ["bt.skill.reply"] = new[] { "히히, 나도 곧 따라잡을 거야!", "흥, 내 {skill|은} {level|이야}! 그 정도야 나도 해!", "축하해! 신들이 기뻐하실 거야.", "박수! 짝짝짝!", "천재? 히히, 나도 천재야!", "노래 불러 줄게! 랄랄라!", "선생님? 그럼 나 학생 할래!", "내 {skill|은} {level}! 나도 대단하지?", "히히, 다음엔 내가 이길 거야!", "저녁 쏜다고? 고기로!", "번개? 나는 천둥이야!", "히히, 손가락 근질근질 나도 그래!", "{pskill} {plevel}... 흥, 금방 넘을 거야!", "오딘이 보셨으면 좋았을 텐데!", "대단해! 나도 같이 연습할래!" },
                ["bt.work.open"] = new[] { "히히, 오늘 일 끝! 맞지, {partner}?", "{partner}, 내일은 재밌는 일 하자!", "일하다 보니 신들 노래가 들렸어!", "나무 열 그루 쓰러뜨렸어! 아마 열한 그루? 히히.", "{partner}, 돌 나르기 시합할래?", "곡괭이질하면 노래가 절로 나와! 땅! 땅!", "오늘 캔 광석 반짝반짝해! 봐 봐!", "{partner}, 일하는 척하고 놀까? 히히, 농담이야.", "울타리 세웠는데 좀 삐뚤어. 멋있지?", "일 많이 하면 밤에 꿈도 안 꿔! 히히.", "{partner}, 내가 더 빨랐지? 그렇지?", "상자에 넣다가 하나 떨어뜨렸어. 쉿!", "땀 났어! 이건 열심히 했다는 증거야!", "{partner}, 다음엔 큰 집 짓자! 엄청 큰 거!", "일 끝나면 뭐 하지? 또 일? 히히." },
                ["bt.work.reply"] = new[] { "히히, 내일 일은 내일의 나한테!", "끝? 그럼 놀자!", "신들도 일하실까? 아닐걸, 히히.", "내가 더 빨랐어! 히히.", "좋아! 시합이다!", "히히, 삐뚤어도 튼튼하면 돼!", "나도 반짝이는 거 캤어!", "쉿, 비밀로 해 줄게.", "큰 집! 탑도 올리자!", "히히, 일하는 거 생각보다 재밌어.", "내일은 내가 이길 거야!", "땅! 땅! 나도 노래 불러!", "히히, 쉬는 것도 일이래.", "다음엔 둘이 같이 하자!", "와, 벌써 다 했어?" },
                ["bt.food.open"] = new[] { "배고파! 꼬르륵 소리가 천둥 같아!", "{partner}, 버섯 구워 먹을래? 히히.", "꿀! 꿀이 먹고 싶어!", "라즈베리 따다가 반은 먹었어. 히히.", "{partner}, 고기 누가 더 잘 굽나 해 보자!", "생선 잡았는데 도망갔어! 히히.", "{partner}, 빵에 꿀 발라 먹으면 최고야!", "소시지! 소시지 냄새 나!", "배불러서 굴러갈 것 같아. 히히.", "{partner}, 블루베리 먹으면 혀가 파래져! 봐!", "솥에 뭐든 넣으면 국이 되지? 히히.", "고기 타 버렸어. 그래도 먹을래!", "{partner}, 내 몫 남겨 뒀지?", "먹고 자고 먹고 자고! 히히.", "오늘 저녁은 뭐야? 뭐야?" },
                ["bt.food.reply"] = new[] { "나도! 나도 줘!", "히히, 내가 다 먹을 거야.", "먹는 게 제일 좋아!", "히히, 반만 줄게. 아니 조금만.", "탄 것도 맛있어!", "꿀은 내 거야! 히히.", "좋아! 불 피우자!", "혀 파래졌어? 히히.", "배고프면 기운이 안 나!", "히히, 남긴 거 없어. 미안!", "나도 꼬르륵 했어!", "고기 굽기 시합이다!", "버섯은 아는 것만! 히히.", "먹고 나서 놀자!", "와, 냄새 좋다!" },
                ["bt.old.open"] = new[] { "옛날에 배 만드는 거 구경했었어. 히히.", "{partner}, 어릴 때 뭐 하고 놀았어?", "할머니가 신들 이야기 해 줬었지!", "어릴 때 염소 쫓다가 진흙에 빠졌어! 히히.", "{partner}, 처음 낚시한 날 신발을 잃어버렸어.", "옛날에 형이랑 눈싸움하면 늘 내가 이겼어!", "{partner}, 고향 축제 기억나? 불 엄청 컸지!", "어릴 땐 트롤이 침대 밑에 사는 줄 알았어. 히히.", "엄마가 만든 꿀빵이 최고였어!", "{partner}, 어릴 때 꿈이 뭐였어? 난 거인!", "옛날에 나무 위에 집 지었었어. 무너졌지만! 히히.", "할아버지 수염 땋아 드렸다가 혼났어.", "{partner}, 처음 노 저었을 때 빙글빙글 돌았어!", "옛날 친구가 나보고 늘 시끄럽다고 했어. 히히.", "어릴 땐 별을 세다 잠들었어." },
                ["bt.old.reply"] = new[] { "히히, 난 나무에 올라갔어!", "옛날 얘기 더 해 줘!", "신들 이야기 좋아!", "히히, 나도 그런 적 있어!", "진짜? 하나 더!", "난 거인이 되고 싶었어!", "그때 나도 같이 있었으면 좋았을걸!", "히히, 지금도 시끄러워.", "꿀빵! 나도 먹고 싶다!", "옛날엔 다 재밌었어!", "히히, 그거 웃기다!", "트롤은 진짜 있었잖아! 히히.", "나도 빙글빙글 돌았어!", "고향 생각하면 배고파져.", "지금도 재밌지? 히히." },
                ["bt.tools.open"] = new[] { "내 도끼한테 이름 붙였어! 히히.", "{partner}, 곡괭이가 날 싫어하나 봐.", "연장도 쉬어야 해, 우리처럼!", "망치로 손가락 칠 뻔했어! 히히.", "{partner}, 새 도끼 반짝반짝하지?", "곡괭이 자루가 삐걱삐걱 노래해!", "{partner}, 내 망치 봤어? 또 어디 뒀지?", "작업대 앞에 서면 대장장이 된 기분이야!", "도끼 휘두르면 휙휙 소리가 좋아! 히히.", "{partner}, 연장 닦아 줬어. 고맙다고 하더라!", "괭이로 땅 고르는 거 재밌어!", "청동 도끼다! 이제 나무가 날 무서워해!", "{partner}, 칼은 나 주고 국자는 네가 해! 히히.", "연장이 무뎌지면 나도 졸려.", "쇠 연장 만들면 엄청 무거울까?" },
